          },
          {
            text: 'Удалить',
            action: () => handleAction('Удалить'),
            theme: 'danger',
          },
        ]}
        renderSwitcher={(props) => (
          <button {...props}>
            <EllipsisVertical />
          </button>
        )}
      />
    </div>
  );
}
